// Helper to create a clean text snippet
const createSnippet = (html: string, length = 150) => {
  if (!html) return '';
  const text = html.replace(/<[^>]+>/g, ''); // Strip HTML tags
  if (text.length <= length) {
    return text;
  }
  return text.substring(0, length) + '...';
};

